#!/usr/bin/env node
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const OUTPUT = join(ROOT, 'src', 'background-ff.js');

const SOURCES = [
    'src/js/store.js',
    'src/js/ticktickapi.js',
    'src/js/oneclickticktick.js',
    'src/service-worker.js'
];

const HEADER = [
    '// Firefox classic background script.',
    '// GENERATED by scripts/bundle-ff.mjs from src/js/store.js, src/js/ticktickapi.js,',
    '// src/js/oneclickticktick.js and src/service-worker.js. Do not edit by hand:',
    '// edit the modules and run `npm run bundle`.',
    ''
].join('\n');

function toClassic(source) {
    return source
        .replace(/\r\n/g, '\n')
        .split('\n')
        .filter(line => !/^\s*import\s/.test(line))
        .map(line => line.replace(/^export\s+(async\s+function|function|const|let|class)\b/, '$1'))
        .join('\n')
        .trim();
}

export function buildBundle() {
    const parts = SOURCES.map(rel => toClassic(readFileSync(join(ROOT, rel), 'utf8')));
    return HEADER + '\n' + parts.join('\n\n') + '\n';
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
    const bundle = buildBundle();
    writeFileSync(OUTPUT, bundle);
    console.log(`bundle: src/background-ff.js (${bundle.split('\n').length} lines)`);
}
